import re

def split_words(txt):
    words = re.findall(r'\b\w+\b|[^\w\s,]', txt)
    if ',' in txt:
        return [word for word in words if word != ',']
    elif any(char.isalpha() for char in txt):
        return [word for word in words if word.isalpha()]
    else:
        return sum(1 for i in range(ord('a'), ord('z')+1) if (i % 2 == 0) and (txt[i] != ' '))
